package com.minova.cloud;
import android.app.*;import android.content.*;import android.graphics.*;import android.graphics.drawable.BitmapDrawable;import android.net.Uri;import android.os.*;import android.view.*;import androidx.test.ext.junit.runners.AndroidJUnit4;import androidx.test.platform.app.InstrumentationRegistry;import org.json.*;import org.junit.Test;import org.junit.runner.RunWith;import java.io.*;import java.util.*;import static org.junit.Assert.*;
@RunWith(AndroidJUnit4.class)
public class PhotoGalleryTest {
    Context context(){return InstrumentationRegistry.getInstrumentation().getTargetContext();}
    CloudApi login()throws Exception{context().getSharedPreferences("qa",0).edit().putString("origin","http://127.0.0.1:4178").commit();return new CloudApi(context(),new CloudApi(context(),null).login("preview","synthetic preview passphrase","",null));}
    interface Check {boolean ready();}void waitFor(Check check)throws Exception{long deadline=System.currentTimeMillis()+15000;while(!check.ready()&&System.currentTimeMillis()<deadline)Thread.sleep(40);assertTrue("Native viewer did not reach its expected state",check.ready());}
    @Test public void fullScreenViewerNavigatesSwipesZoomsAndKeepsTheSelectedPhoto()throws Exception{
        CloudApi api=login();String folder="Viewer QA "+UUID.randomUUID();api.ensureFolder(folder);List<PhotoGalleryDialog.Photo> photos=new ArrayList<>();int[] colors={Color.RED,Color.GREEN,Color.BLUE};
        for(int i=0;i<3;i++){File file=new File(context().getCacheDir(),"viewer-test-"+i+".png");Bitmap bitmap=Bitmap.createBitmap(240,160,Bitmap.Config.ARGB_8888);bitmap.eraseColor(colors[i]);try(OutputStream stream=new FileOutputStream(file)){bitmap.compress(Bitmap.CompressFormat.PNG,100,stream);}bitmap.recycle();String target=new UploadEngine(api,()->false).upload(Uri.fromFile(file),new UploadEngine.Info(file.getName(),file.length()),folder+"/"+file.getName(),AppUpdater.hash(file),false,(a,b,c)->{});JSONObject item=api.request("/api/files?path="+CloudApi.encode(folder),"GET",null).getJSONArray("items").getJSONObject(i);photos.add(new PhotoGalleryDialog.Photo(item,item,null));file.delete();}
        Instrumentation instrumentation=InstrumentationRegistry.getInstrumentation();Activity owner=instrumentation.startActivitySync(new Intent(context(),MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));PhotoGalleryDialog[] viewer={null};int[] saved={-1};
        try{instrumentation.runOnMainSync(()->{viewer[0]=new PhotoGalleryDialog(owner,api,photos,0,(item,save)->saved[0]=photos.indexOf(photos.stream().filter(photo->photo.original==item).findFirst().get()));viewer[0].show();});PhotoGalleryDialog dialog=viewer[0];waitFor(()->dialog.status.getVisibility()==View.GONE);assertEquals("1 of 3",dialog.counter.getText().toString());assertFalse(dialog.previous.isEnabled());
            instrumentation.runOnMainSync(()->dialog.next.performClick());waitFor(()->dialog.index==1&&dialog.status.getVisibility()==View.GONE);assertEquals(Color.GREEN,((BitmapDrawable)dialog.image.getDrawable()).getBitmap().getPixel(0,0));
            instrumentation.runOnMainSync(()->{dialog.move(1);dialog.move(-1);dialog.move(-1);});waitFor(()->dialog.index==0&&dialog.status.getVisibility()==View.GONE);assertEquals(Color.RED,((BitmapDrawable)dialog.image.getDrawable()).getBitmap().getPixel(0,0));
            instrumentation.runOnMainSync(()->dialog.image.zoomTo(2.5f,dialog.image.getWidth()/2f,dialog.image.getHeight()/2f));assertEquals(2.5f,dialog.image.zoom,.01f);instrumentation.runOnMainSync(()->dialog.image.fit());assertEquals(1f,dialog.image.zoom,.01f);
            int[] location=new int[2];instrumentation.runOnMainSync(()->dialog.image.getLocationOnScreen(location));float y=location[1]+dialog.image.getHeight()/2f,start=location[0]+dialog.image.getWidth()*.8f,end=location[0]+dialog.image.getWidth()*.2f;long down=SystemClock.uptimeMillis();
            for(int step=0;step<=11;step++){int action=step==0?MotionEvent.ACTION_DOWN:step==11?MotionEvent.ACTION_UP:MotionEvent.ACTION_MOVE;MotionEvent event=MotionEvent.obtain(down,SystemClock.uptimeMillis(),action,start+(end-start)*step/11f,y,0);instrumentation.sendPointerSync(event);event.recycle();SystemClock.sleep(20);}waitFor(()->dialog.index==1&&dialog.status.getVisibility()==View.GONE);assertEquals(Color.GREEN,((BitmapDrawable)dialog.image.getDrawable()).getBitmap().getPixel(0,0));
            instrumentation.runOnMainSync(()->{for(View view:allViews(dialog.getWindow().getDecorView()))if(android.text.TextUtils.equals("Save current photo to phone",view.getContentDescription()))view.performClick();});assertEquals(1,saved[0]);SystemClock.sleep(220);instrumentation.runOnMainSync(()->{View root=dialog.getWindow().getDecorView();Bitmap preview=Bitmap.createBitmap(root.getWidth(),root.getHeight(),Bitmap.Config.ARGB_8888);root.draw(new Canvas(preview));try(OutputStream output=new FileOutputStream(new File(context().getCacheDir(),"gallery-preview.png"))){preview.compress(Bitmap.CompressFormat.PNG,100,output);}catch(Exception error){throw new RuntimeException(error);}finally{preview.recycle();}});instrumentation.runOnMainSync(dialog::dismiss);waitFor(()->dialog.closed&&dialog.io.isShutdown());
        }finally{instrumentation.runOnMainSync(()->{if(viewer[0]!=null)viewer[0].dismiss();owner.finish();});api.request("/api/logout","POST",new JSONObject());}
    }
    List<View> allViews(View view){List<View> result=new ArrayList<>();result.add(view);if(view instanceof ViewGroup)for(int i=0;i<((ViewGroup)view).getChildCount();i++)result.addAll(allViews(((ViewGroup)view).getChildAt(i)));return result;}
    @Test public void movedLegacyBackupsReuseVerifiedReceiptsAndKeepPhoneOriginals()throws Exception{
        CloudApi api=login();OffloadSafetyTest helpers=new OffloadSafetyTest();MediaAsset photo=helpers.photo();String user=api.userId(),old="Phone backups/Android-legacy/Photos/"+photo.name;api.ensureFolder("Phone backups/Android-legacy/Photos");String hash=new UploadEngine(api,()->false).checksum(photo.uri);new UploadEngine(api,()->false).upload(photo.uri,new UploadEngine.Info(photo.name,photo.size),old,hash,true,(a,b,c)->{});
        try(BackupStore receipts=new BackupStore(context());OffloadStore store=new OffloadStore(context())){
            receipts.record(user,photo.assetKey(),old);String existing=store.create(user,Collections.singletonList(photo));store.uploaded(user,existing,photo.uri,hash,old);store.state(user,existing,"ready","Synthetic legacy backup");
            SafeOffload.Proof proof=SafeOffload.verify(api,store,existing,()->false);assertNotNull(SafeOffload.deletionRequest(context(),proof));OffloadStore.Item relocated=store.items(user,existing).get(0);assertTrue(relocated.target.startsWith("Pictures/Phone backups/"));assertTrue(helpers.exists(photo.uri));assertTrue(SafeOffload.matches(api,relocated.target,hash,photo.size));
            String another=store.create(user,Collections.singletonList(photo));SafeOffload.prepare(api,store,another,()->false,(a,b,c)->{});assertEquals(relocated.target,store.items(user,another).get(0).target);assertEquals(1,api.request("/api/library?kind=photos&album=phone-backups&q="+CloudApi.encode(photo.name),"GET",null).getJSONArray("items").length());assertTrue(helpers.exists(photo.uri));
            // A later historical root with different bytes must not take over an older receipt.
            api.ensureFolder("Phone backups/Android-legacy/Photos");File wrong=new File(context().getCacheDir(),"wrong-legacy.bin");try(OutputStream output=new FileOutputStream(wrong)){output.write(new byte[(int)photo.size]);}new UploadEngine(api,()->false).upload(Uri.fromFile(wrong),new UploadEngine.Info(photo.name,wrong.length()),old,AppUpdater.hash(wrong),false,(a,b,c)->{});wrong.delete();api.prepareBackupAlbum();assertEquals(relocated.target,api.resolveBackupTarget(old,hash,photo.size));assertTrue(helpers.exists(photo.uri));
        }finally{context().getContentResolver().delete(photo.uri,null,null);api.request("/api/logout","POST",new JSONObject());}
    }
}
